"""Deterministic, authored synthetic pilot dataset. No model or web calls.
Run from the project root: python data/build_data.py
All paraphrases of a scenario stay in the same split.
"""
from pathlib import Path
import json
import hashlib
from collections import Counter

ROOT = Path(__file__).resolve().parents[1]
SYSTEM = ('Вы — помощник по теме «Дом и квартира». Отвечайте по-русски, понятно и по существу. '
          'Не выдавайте предположения за установленный факт.')
SCENARIOS = []

def add(category, split, name, questions, answer, actions=(), risk='low', sources=()):
    qs = questions.split(' || ')
    assert len(qs) == 3, (name, len(qs))
    SCENARIOS.append(dict(category=category, split=split, family_id=f'{category}_{name}',
                          questions=qs, answer=answer, required_actions=list(actions),
                          risk=risk, source_ids=list(sources)))

