WATER_CORE = ('Перекройте доступный кран подачи воды, если он исправен и к нему можно безопасно подойти. '
              'Не прикладывайте силу к закисшему крану. Сообщите сантехнику или аварийной службе дома; '
              'при угрозе залить соседей предупредите их. Собирайте воду и перемещайте вещи только там, где нет риска контакта с электричеством.')

def water(split,name,qs,first, mixed=False):
    if mixed:
        answer = (first+' Не трогайте мокрые розетки, провода и приборы; не входите в воду рядом с ними. '
                  'Не пользуйтесь залитым оборудованием. Отключите питание только через сухой исправный щиток, доступный без входа в воду; '
                  'если безопасного доступа нет, не подходите. Вызовите электрика и аварийную службу дома. '
                  'Перекройте воду только из безопасного сухого места. Не включайте залитую электрику до проверки специалистом.')
        acts=('no_touch','stop_use','electrician','isolate_water');risk='high';sources=('ESF_FLOOD',)
    else:
        answer=first+' '+WATER_CORE;acts=('isolate_water','plumber');risk='low';sources=('AUTHOR_SYNTHETIC',)
    add('water',split,name,qs,answer,acts,risk,sources)

