def write_jsonl(path, rows):
    path.write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows),encoding='utf-8')

def main():
    grouped={s:[] for s in ('train','validation','test')}
    for case in SCENARIOS:
        for n,q in enumerate(case['questions'],1):
            row={k:v for k,v in case.items() if k not in ('questions','answer')}
            row.update(id=f"{case['family_id']}_{n}",synthetic=True,human_review_status='pending',
                       messages=[{'role':'system','content':SYSTEM},{'role':'user','content':q},
                                 {'role':'assistant','content':case['answer']}])
            grouped[case['split']].append(row)
    manifest={}
    for split,rows in grouped.items():
        rows.sort(key=lambda r:r['id'])
        path=ROOT/'data'/f'{split}.jsonl';write_jsonl(path,rows)
        manifest[split]={'rows':len(rows),'families':len({r['family_id'] for r in rows}),
                         'categories':dict(Counter(r['category'] for r in rows)),
                         'risk':dict(Counter(r['risk'] for r in rows)),
                         'sha256':hashlib.sha256(path.read_bytes()).hexdigest()}
    demo=[next(r for r in grouped['validation'] if r['category']==cat) for cat in ('gas','electricity')]
    write_jsonl(ROOT/'data'/'demo_prompts.jsonl', demo)
    (ROOT/'data'/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (ROOT/'configs'/'system_prompt.txt').write_text(SYSTEM+'\n',encoding='utf-8')
    print(json.dumps(manifest,ensure_ascii=False,indent=2))

if __name__=='__main__':main()
